INSERT INTO translation_cache VALUES('hash_oop_en_ml','Object-Oriented Programming','ml','ഒബ്ജക്റ്റ്-ഓറിയന്റഡ് പ്രോഗ്രാമിംഗ്','2026-10-27 10:26:00');
INSERT INTO translation_cache VALUES('2ad1f44a131165a1ec1edd00f89c0a7c4e2162c161d4ee12dec6d26cbce39d23',unistr('Object-Oriented Programming (OOP) is a fundamental programming paradigm based on the concept of objects. In Java, classes act as blueprints for creating objects that encapsulate state and behavior. The core pillars of OOP include Encapsulation, Abstraction, Inheritance, and Polymorphism.\u000a\u000aEncapsulation ensures data protection through private variables and public accessor methods. Inheritance allows a subclass to inherit fields and methods from a superclass, fostering high code reusability. Polymorphism enables dynamic method dispatch, where method calls are resolved at runtime.\u000a\u000aThrough robust exception handling and SOLID design principles, Java software engineers construct scalable, maintainable, and high-performance applications capable of processing massive data sets.'),'ml','ഒബ്ജക്റ്റ് ഓറിയന്റഡ് പ്രോഗ്രാമിങ് (OOP) എന്നത് ഒബ്ജക്റ്റുകളുടെ ആശയത്തെ അടിസ്ഥാനമാക്കിയുള്ള ഒരു അടിസ്ഥാന പ്രോഗ്രാമിങ് മാതൃകയാണ്. ജാവയിൽ, അവസ്ഥയും പെരുമാറ്റവും ഉൾക്കൊള്ളുന്ന വസ്തുക്കൾ സൃഷ്ടിക്കുന്നതിനുള്ള ബ്ലൂപ്രിന്റുകളായി ക്ലാസുകൾ പ്രവർത്തിക്കുന്നു. എൻ‌കാപ്സുലേഷൻ, അമൂർത്തീകരണം, അനന്തരാവകാശം, പോളിമോർഫിസം എന്നിവയാണ് OOP-യുടെ പ്രധാന തൂണുകൾ. സ്വകാര്യ വേരിയബിളുകളിലൂടെയും പൊതു ആക്സസർ രീതികളിലൂടെയും ഡാറ്റ പരിരക്ഷ ഉറപ്പാക്കുന്നു. ഉയർന്ന കോഡ് പുനരുപയോഗം പ്രോത്സാഹിപ്പിക്കുന്ന ഒരു സൂപ്പർക്ലാസിൽ നിന്ന് ഫീൽഡുകളും രീതികളും അവകാശമാക്കാൻ ഇൻഹെറിറ്റൻസ് ഒരു ഉപവിഭാഗത്തെ അനുവദിക്കുന്നു. റൺടൈമിൽ രീതി കോളുകൾ പരിഹരിക്കുന്ന ഡൈനാമിക് രീതി ഡിസ്പാച്ച് പോളിമോർഫിസം പ്രാപ്തമാക്കുന്നു. ശക്തമായ ഒഴിവാക്കൽ കൈകാര്യം ചെയ്യലിലൂടെയും സോളിഡ് ഡിസൈൻ തത്വങ്ങളിലൂടെയും, ജാവ സോഫ്റ്റ്വെയർ എഞ്ചിനീയർമാർ വിപുലമായ ഡാറ്റാ സെറ്റുകൾ പ്രോസസ്സ് ചെയ്യാൻ പ്രാപ്തിയുള്ള അളക്കാവുന്നതും പരിപാലിക്കാവുന്നതും ഉയർന്ന പ്രകടനമുള്ളതുമായ ആപ്ലിക്കേഷനുകൾ നിർമ്മിക്കുന്നു.','2026-10-27 22:22:09');
INSERT INTO translation_cache VALUES('1164416fda881beb4765666c5f2ef7530aee334a75f15074cc2582a825d3655e',unistr('If you can keep your head when all about you   \u000a    Are losing theirs and blaming it on you,   \u000aIf you can trust yourself when all men doubt you,\u000a    But make allowance for their doubting too;   \u000aIf you can wait and not be tired by waiting,\u000a    Or being lied about, don’t deal in lies,\u000aOr being hated, don’t give way to hating,\u000a    And yet don’t look too good, nor talk too wise:\u000a\u000aIf you can dream—and not make dreams your master;   \u000a    If you can think—and not make thoughts your aim;   \u000aIf you can meet with Triumph and Disaster\u000a    And treat those two impostors just the same;   \u000aIf you can bear to hear the truth you’ve spoken\u000a    Twisted by knaves to make a trap for fools,\u000aOr watch the things you gave your life to, broken,\u000a    And stoop and build ’em up with worn-out tools:\u000a\u000aIf you can make one heap of all your winnings\u000a    And risk it on one turn of pitch-and-toss,\u000aAnd lose, and start again at your beginnings\u000a    And never breathe a word about your loss;\u000aIf you can force your heart and nerve and sinew\u000a    To serve your turn long after they are gone,   \u000aAnd so hold on when there is nothing in you\u000a    Except the Will which says to them: ‘Hold on!’\u000a\u000aIf you can talk with crowds and keep your virtue,   \u000a    Or walk with Kings—nor lose the common touch,\u000aIf neither foes nor loving friends can hurt you,\u000a    If all men count with you, but none too much;\u000aIf you can fill the unforgiving minute\u000a    With sixty seconds’ worth of distance run,   \u000aYours is the Earth and everything that’s in it,   \u000a    And—which is more—you’ll be a Man, my son!'),'hi',unistr('यदि आप अपने बारे में सब कुछ होने पर अपना सिर रख सकते हैं   \u000a उन्हें खो रहे हैं और इसे आप पर दोष दे रहे हैं,   \u000aयदि आप अपने आप पर भरोसा कर सकते हैं जब सभी लोग आप पर संदेह करते हैं,\u000a लेकिन उनके संदेह के लिए भी भत्ता दें;   \u000aअगर आप इंतज़ार कर सकते हैं और इंतज़ार करके थक नहीं सकते,\u000a या झूठ बोलना, झूठ न बोलना,\u000aया नफरत की जा रही है, नफरत का रास्ता न दें,\u000a और फिर भी बहुत अच्छा मत देखो, और न ही बहुत बुद्धिमान बात करो:\u000a यदि आप सपने देख सकते हैं - और सपने को अपना मालिक नहीं बना सकते हैं; यदि आप सोच सकते हैं - और विचारों को अपना लक्ष्य नहीं बना सकते हैं;   \u000aयदि आप विजय और आपदा के साथ मिल सकते हैं\u000a और उन दो धोखेबाज़ों के साथ एक जैसा व्यवहार करें;   \u000aयदि आप अपने द्वारा बोले गए सत्य को सुनने के लिए सहन कर सकते हैं\u000a मूर्खों के लिए एक जाल बनाने के लिए चाकू से घुमाया गया,\u000aया उन चीज़ों को देखो जिन्हें तुमने अपना जीवन दिया है, टूटी हुई,\u000a और घिसे - पिटे टूल के साथ झुककर उनका निर्माण करें:\u000a यदि आप अपनी सभी जीत का एक ढेर बना सकते हैं और इसे पिच - एंड - टॉस के एक मोड़ पर जोखिम में डालें,\u000aऔर खो देते हैं, और अपनी शुरुआत में फिर से शुरू करते हैं\u000a और कभी भी अपने नुकसान के बारे में एक शब्द भी न बोलें;\u000aयदि आप अपने दिल और तंत्रिका और साइन को मजबूर कर सकते हैं\u000a उनके चले जाने के लंबे समय बाद अपनी बारी पूरी करने के लिए,   \u000aऔर इसलिए पकड़ो जब तुम में कुछ भी नहीं है\u000a सिवाय उस वसीयत के, जो उनसे कहे: ‘धैर्य रखो!\u000a यदि आप भीड़ के साथ बात कर सकते हैं और अपने गुणों को बनाए रख सकते हैं, या किंग्स के साथ चलना - न ही आम स्पर्श खोना,\u000aअगर न तो दुश्मन और न ही प्यार करने वाले दोस्त आपको चोट पहुंचा सकते हैं,\u000a यदि सभी लोग आपके साथ गिने जाते हैं, लेकिन बहुत ज्यादा नहीं;\u000aअगर आप क्षमा न करने वाला मिनट भर सकते हैं\u000a साठ सेकंड की दूरी के साथ,   \u000aपृथ्वी और उसमें जो कुछ भी है वह तुम्हारा है,   \u000a और - जो ज़्यादा है -तुम एक आदमी बनोगी, मेरे बेटे!'),'2026-10-27 22:59:10');
INSERT INTO translation_cache VALUES('39ef675e00460ac747b80ba0f83f836f66a83f1cbcea7699e732c78d48be4a19',unistr('If you can keep your head when all about you   \u000a    Are losing theirs and blaming it on you,   \u000aIf you can trust yourself when all men doubt you,\u000a    But make allowance for their doubting too;   \u000aIf you can wait and not be tired by waiting,\u000a    Or being lied about, don’t deal in lies,\u000aOr being hated, don’t give way to hating,\u000a    And yet don’t look too good, nor talk too wise:\u000a\u000aIf you can dream—and not make dreams your master;   \u000a    If you can think—and not make thoughts your aim;   \u000aIf you can meet with Triumph and Disaster\u000a    And treat those two impostors just the same;   \u000aIf you can bear to hear the truth you’ve spoken\u000a    Twisted by knaves to make a trap for fools,\u000aOr watch the things you gave your life to, broken,\u000a    And stoop and build ’em up with worn-out tools:\u000a\u000aIf you can make one heap of all your winnings\u000a    And risk it on one turn of pitch-and-toss,\u000aAnd lose, and start again at your beginnings\u000a    And never breathe a word about your loss;\u000aIf you can force your heart and nerve and sinew\u000a    To serve your turn long after they are gone,   \u000aAnd so hold on when there is nothing in you\u000a    Except the Will which says to them: ‘Hold on!’\u000a\u000aIf you can talk with crowds and keep your virtue,   \u000a    Or walk with Kings—nor lose the common touch,\u000aIf neither foes nor loving friends can hurt you,\u000a    If all men count with you, but none too much;\u000aIf you can fill the unforgiving minute\u000a    With sixty seconds’ worth of distance run,   \u000aYours is the Earth and everything that’s in it,   \u000a    And—which is more—you’ll be a Man, my son!'),'ml',unistr('നിങ്ങളെക്കുറിച്ച് ചിന്തിക്കുമ്പോൾ നിങ്ങൾക്ക് തലയുയർത്തിപ്പിടിക്കാൻ കഴിയുമെങ്കിൽ   \u000a അവരുടേത് നഷ്ടപ്പെടുകയും നിങ്ങളുടെ മേൽ കുറ്റപ്പെടുത്തുകയും ചെയ്യുന്നു,   \u000aഎല്ലാ മനുഷ്യരും നിങ്ങളെ സംശയിക്കുമ്പോൾ നിങ്ങൾക്ക് സ്വയം വിശ്വസിക്കാൻ കഴിയുമെങ്കിൽ,\u000a എന്നാൽ അവരുടെ സംശയത്തിനും അലവൻസ് നൽകുക;   \u000aനിങ്ങൾക്ക് കാത്തിരിക്കാനും കാത്തിരിക്കാനും ക്ഷീണിതനാകാതിരിക്കാനും കഴിയുമെങ്കിൽ,\u000a അല്ലെങ്കിൽ നുണ പറയുമ്പോൾ, നുണ പറയരുത്,\u000aഅല്ലെങ്കിൽ വെറുക്കപ്പെടുമ്പോൾ, വെറുപ്പിന് വഴിമാറരുത്,\u000a എന്നിട്ടും വളരെ നല്ലതായി കാണരുത്, വളരെ ജ്ഞാനപൂർവ്വം സംസാരിക്കരുത്:\u000a നിങ്ങൾക്ക് സ്വപ്നം കാണാൻ കഴിയുമെങ്കിൽ-സ്വപ്നങ്ങളെ നിങ്ങളുടെ യജമാനനാക്കാതിരുന്നാൽ; നിങ്ങൾക്ക് ചിന്തിക്കാൻ കഴിയുമെങ്കിൽ - ചിന്തകളെ നിങ്ങളുടെ ലക്ഷ്യമാക്കാതിരിക്കുക;   \u000aനിങ്ങൾക്ക് വിജയവും ദുരന്തവും നേരിടാൻ കഴിയുമെങ്കിൽ\u000a ആ രണ്ട് വഞ്ചകരോടും ഒരുപോലെ പെരുമാറുക;   \u000aനിങ്ങൾ സംസാരിച്ച സത്യം കേൾക്കാൻ നിങ്ങൾക്ക് കഴിയുമെങ്കിൽ\u000a വിഡ്ഢികൾക്ക് ഒരു കെണി ഉണ്ടാക്കാൻ കത്തികളാൽ വളച്ചൊടിച്ചു,\u000aഅല്ലെങ്കിൽ നിങ്ങൾ നിങ്ങളുടെ ജീവൻ നൽകിയ, തകർന്ന കാര്യങ്ങൾ കാണുക,\u000a തളർന്നുപോയ ഉപകരണങ്ങൾ ഉപയോഗിച്ച് കുനിഞ്ഞ് അവയെ കെട്ടിപ്പടുക്കുക:\u000a നിങ്ങളുടെ എല്ലാ വിജയങ്ങളുടെയും ഒരു കൂമ്പാരം ഉണ്ടാക്കാൻ നിങ്ങൾക്ക് കഴിയുമെങ്കിൽ പിച്ച്-ആൻഡ്-ടോസിന്റെ ഒരു ടേണിൽ അത് റിസ്ക് ചെയ്യുക,\u000aനഷ്ടപ്പെടുകയും നിങ്ങളുടെ തുടക്കങ്ങളിൽ നിന്ന് വീണ്ടും ആരംഭിക്കുകയും ചെയ്യുക\u000a നിങ്ങളുടെ നഷ്ടത്തെക്കുറിച്ച് ഒരു വാക്കുപോലും ശ്വസിക്കരുത്;\u000aനിങ്ങളുടെ ഹൃദയത്തെയും നാഡികളെയും ഞരമ്പുകളെയും നിർബന്ധിക്കാൻ കഴിയുമെങ്കിൽ\u000a അവർ പോയതിനുശേഷം നിങ്ങളുടെ ഊഴം നിറവേറ്റാൻ,   \u000aഅതിനാൽ നിങ്ങളിൽ ഒന്നും ഇല്ലാതിരിക്കുമ്പോൾ മുറുകെ പിടിക്കുക\u000a അവരോടു പറയുന്ന ഇച്ഛയൊഴികെ: ‘നിൽക്കൂ!’\u000a നിങ്ങൾക്ക് ജനക്കൂട്ടവുമായി സംസാരിക്കാനും നിങ്ങളുടെ സദ്‌ഗുണം കാത്തുസൂക്ഷിക്കാനും കഴിയുമെങ്കിൽ, അല്ലെങ്കിൽ രാജാക്കന്മാരോടൊപ്പം നടക്കുകയോ പൊതുവായ സ്പർശം നഷ്ടപ്പെടുകയോ ചെയ്യരുത്,\u000aശത്രുക്കൾക്കോ സ്നേഹനിധികളായ സുഹൃത്തുക്കൾക്കോ നിങ്ങളെ ഉപദ്രവിക്കാൻ കഴിയുന്നില്ലെങ്കിൽ,\u000a സകലമനുഷ്യരും നിന്നോടുകൂടെ എണ്ണുന്നു എങ്കിലും അധികമൊന്നുമില്ലെങ്കിൽ;\u000aനിങ്ങൾക്ക് ക്ഷമിക്കാത്ത നിമിഷം പൂരിപ്പിക്കാൻ കഴിയുമെങ്കിൽ\u000a അറുപത് സെക്കൻഡ് ദൈർഘ്യമുള്ള ദൂരം ഓടിയാൽ,   \u000aഭൂമിയും അതിലുള്ളതൊക്കെയും നിന്റേതാണ്,   \u000a പിന്നെ-ഏതാണോ കൂടുതൽ-എന്റെ മകനേ, നീ ഒരു മനുഷ്യനാകും!'),'2026-10-27 22:59:21');
INSERT INTO translation_cache VALUES('c369970f0f76402aa407cd8f64c410e27adb7c98ecbfdf434e5fe15749d9de91','a cat ate a whole pizza and got sick','hi','एक बिल्ली ने पूरा पिज्जा खाया और बीमार हो गई','2026-10-28 10:32:09');
INSERT INTO translation_cache VALUES('6d2b5492f4b993748e63ce68c71926ab3b98ada7c20af8bce07aca6803ec462b','a cat ate a whole pizza and got sick','ml','ഒരു പൂച്ച ഒരു പിസ്സ മുഴുവൻ കഴിക്കുകയും അസുഖം ബാധിക്കുകയും ചെയ്തു','2026-10-28 10:32:21');
