INSERT INTO translation_cache VALUES('f9bb349617ab8d73529513c28dd3884b6aa49074b1078c4351145fb1ac59cdb2',unistr('my name is johnz, vaishnav has jihnz,johnz has vaishnav\u000a but naveen is gay.\u000adrgdghdhdzbsgfhfxghghxfbxfghfgh'),'hi',unistr('मेरा नाम जॉनज़ है, वैष्णव के पास जिह्न्ज़ है, जॉनज़के पास वैष्णव है\u000a लेकिन नवीन समलैंगिक है.\u000adrgdghdhdzbsgfhfxghxfbxfghfgh'),'2026-10-28 11:11:13');
INSERT INTO translation_cache VALUES('64cb4261160b5a433881e735708cdfdfc7ee66ae6ca0746fbebd473038ec798c',unistr('my name is johnz, vaishnav has jihnz,johnz has vaishnav\u000a but naveen is gay.\u000adrgdghdhdzbsgfhfxghghxfbxfghfgh'),'ml',unistr('എന്റെ പേര് ജോൺസ്, വൈഷ്ണവിന് ജിഹ്നാസ് ഉണ്ട്,ജോൺസിന് വൈഷ്ണവ് ഉണ്ട്\u000a എന്നാൽ നവീൻ സ്വവർഗാനുരാഗിയാണ്.\u000adrgdghdhdzbsgffxghghghxfxfxfghfgh'),'2026-10-28 11:11:23');
INSERT INTO translation_cache VALUES('bfaed93c3f65073decd0eadd3b6d5d52ee51450bd441e96faa46ecd449d273b4',unistr('Whose woods these are I think I know.   \u000aHis house is in the village though;   \u000aHe will not see me stopping here   \u000aTo watch his woods fill up with snow.   \u000a\u000aMy little horse must think it queer   \u000aTo stop without a farmhouse near   \u000aBetween the woods and frozen lake   \u000aThe darkest evening of the year.   \u000a\u000aHe gives his harness bells a shake   \u000aTo ask if there is some mistake.   \u000aThe only other sound’s the sweep   \u000aOf easy wind and downy flake.   \u000a\u000aThe woods are lovely, dark and deep,   \u000aBut I have promises to keep,   \u000aAnd miles to go before I sleep,   \u000aAnd miles to go before I sleep.'),'hi',unistr('मुझे लगता है कि ये किसके जंगल हैं. हालांकि उसका घर गाँव में है;   \u000aवह मुझे यहाँ रुकते हुए नहीं देखेगा   \u000aउसके जंगल को बर्फ से भरते हुए देखने के लिए। मेरे छोटे घोड़े को यह अजीब लगता होगा   \u000aपास में फ़ार्महाउस के बिना रुकना   \u000aजंगल और जमे हुए झील के बीच   \u000aसाल की सबसे अंधेरी शाम। वह अपनी हार्नेस की घंटी को एक हिला देता है   \u000aयह पूछने के लिए कि क्या कोई गलती है। एकमात्र अन्य ध्वनि स्वीप है   \u000aआसान हवा और डाउनी फ्लेक का। जंगल सुंदर, गहरे और गहरे हैं,   \u000aलेकिन मेरे पास रखने के वादे हैं,   \u000aऔर सोने से पहले मीलों दूर जाना है,   \u000aऔर सोने से पहले मीलों दूर जाना है.'),'2026-10-28 11:26:44');
INSERT INTO translation_cache VALUES('0444b01f60eba0dd08bfa98b418b96abe0a2a6f2116eae297905e11e551e1b4c',unistr('Whose woods these are I think I know.   \u000aHis house is in the village though;   \u000aHe will not see me stopping here   \u000aTo watch his woods fill up with snow.   \u000a\u000aMy little horse must think it queer   \u000aTo stop without a farmhouse near   \u000aBetween the woods and frozen lake   \u000aThe darkest evening of the year.   \u000a\u000aHe gives his harness bells a shake   \u000aTo ask if there is some mistake.   \u000aThe only other sound’s the sweep   \u000aOf easy wind and downy flake.   \u000a\u000aThe woods are lovely, dark and deep,   \u000aBut I have promises to keep,   \u000aAnd miles to go before I sleep,   \u000aAnd miles to go before I sleep.'),'ml',unistr('ഇവ ആരുടെ കാടുകളാണെന്ന് എനിക്കറിയാം. അവന്റെ വീട് ഗ്രാമത്തിലാണ്;   \u000aഞാൻ ഇവിടെ നിർത്തുന്നത് അവൻ കാണില്ല   \u000aഅവന്റെ കാടുകളിൽ മഞ്ഞ് നിറയുന്നത് കാണാൻ. എന്റെ ചെറിയ കുതിര അത് രസകരമാണെന്ന് ചിന്തിക്കണം   \u000aസമീപത്ത് ഒരു ഫാംഹൗസ് ഇല്ലാതെ നിർത്താൻ   \u000aകാടിനും മരവിച്ച തടാകത്തിനുമിടയിൽ   \u000aവർഷത്തിലെ ഏറ്റവും ഇരുണ്ട സായാഹ്നം. അവൻ തന്റെ ഹാർനെസ് ബെല്ലുകൾ കുലുക്കുന്നു   \u000aഎന്തെങ്കിലും തെറ്റുണ്ടോ എന്ന് ചോദിക്കാൻ. മറ്റൊരു ശബ്ദം സ്വീപ്പ് മാത്രമാണ്   \u000aഎളുപ്പത്തിൽ വീശുന്ന കാറ്റും വീശിയടിക്കുന്ന ഫ്ലേക്കും. കാടുകൾ മനോഹരവും ഇരുണ്ടതും ആഴമേറിയതുമാണ്,   \u000aഎന്നാൽ എനിക്ക് പാലിക്കാൻ വാഗ്ദാനങ്ങളുണ്ട്,   \u000aഞാൻ ഉറങ്ങുന്നതിനുമുമ്പ് മൈലുകൾ സഞ്ചരിക്കേണ്ടതുണ്ട്,   \u000aഞാൻ ഉറങ്ങുന്നതിനുമുമ്പ് മൈലുകൾ സഞ്ചരിക്കേണ്ടതുണ്ട്.'),'2026-10-28 11:26:51');
INSERT INTO translation_cache VALUES('d0c42a873828ffc4ab14f6d3d67338a00604e2438ff65883175ffdcf15ca171a',unistr('Something there is that doesn’t love a wall,\u000aThat sends the frozen-ground-swell under it,\u000aAnd spills the upper boulders in the sun;\u000aAnd makes gaps even two can pass abreast.\u000aThe work of hunters is another thing:\u000aI have come after them and made repair\u000aWhere they have left not one stone on a stone,\u000aBut they would have the rabbit out of hiding,\u000aTo please the yelping dogs. The gaps I mean,\u000aNo one has seen them made or heard them made,\u000aBut at spring mending-time we find them there.\u000aI let my neighbor know beyond the hill;\u000aAnd on a day we meet to walk the line\u000aAnd set the wall between us once again.\u000aWe keep the wall between us as we go.\u000aTo each the boulders that have fallen to each.\u000aAnd some are loaves and some so nearly balls\u000aWe have to use a spell to make them balance:\u000a‘Stay where you are until our backs are turned!’\u000aWe wear our fingers rough with handling them.\u000aOh, just another kind of out-door game,\u000aOne on a side. It comes to little more:\u000aThere where it is we do not need the wall:\u000aHe is all pine and I am apple orchard.\u000aMy apple trees will never get across\u000aAnd eat the cones under his pines, I tell him.\u000aHe only says, ‘Good fences make good neighbors.’\u000aSpring is the mischief in me, and I wonder\u000aIf I could put a notion in his head:\u000a‘Why do they make good neighbors? Isn’t it\u000aWhere there are cows? But here there are no cows.\u000aBefore I built a wall I’d ask to know\u000aWhat I was walling in or walling out,\u000aAnd to whom I was like to give offense.\u000aSomething there is that doesn''t love a wall,\u000aThat wants it down.’ I could say ‘Elves’ to him,\u000aBut it’s not elves exactly, and I’d rather\u000aHe said it for himself. I see him there\u000aBringing a stone grasped firmly by the top\u000aIn each hand, like an old-stone savage armed.\u000aHe moves in darkness as it seems to me,\u000aNot of woods only and the shade of trees.\u000aHe will not go behind his father’s saying,\u000aAnd he likes having thought of it so well\u000aHe says again, ‘Good fences make good neighbors.’'),'hi',unistr('कुछ तो है जो दीवार से प्यार नहीं करता,\u000a458941ec00fd20f22c6168237a5d2eaaवह इसके नीचे जमी हुई जमीन-प्रफुल्लित भेजता है,\u000a458941ec00fd20f22c6168237a5d2eaaऔर ऊपरी शिलाओं को धूप में गिरा देता है;\u000a458941ec00fd20f22c6168237a5d2eaaऔर यहां तक ​​कि दो लोग भी एक साथ गुजर सकें, अंतराल बनाता है। 458941ec00fd20f22c6168237a5d2eaaशिकारियों का काम दूसरी बात है:\u000a458941ec00fd20f22c6168237a5d2eaaमैं उनके पीछे आया हूं और मरम्मत की है\u000a458941ec00fd20f22c6168237a5d2eaaजहाँ उन्होंने एक पत्थर पर एक भी पत्थर नहीं छोड़ा है,\u000a458941ec00fd20f22c6168237a5d2eaaलेकिन वे खरगोश को छिपने से बचा लेंगे,\u000a458941ec00fd20f22c6168237a5d2eaaचिल्लाते कुत्तों को खुश करने के लिए.458941ec00fd20f22c6168237a5d2eaa अंतराल जो मेरा मतलब है,\u000aकिसी ने न तो उन्हें बनाया हुआ देखा है और न ही उन्हें बनाया हुआ सुना है,\u000aलेकिन वसंत में मरम्मत के समय हम उन्हें वहां पाते हैं। मैंने पहाड़ी के पार अपने पड़ोसी को बताया;\u000aऔर एक दिन हम लाइन पर चलने के लिए मिलते हैं\u000aऔर हमारे बीच एक बार फिर दीवार खड़ी कर दी. जैसे - जैसे हम चलते हैं, हम दीवार को अपने बीच रखते हैं। प्रत्येक पत्थरों के लिए जो प्रत्येक पर गिर गए हैं। और कुछ रोटियाँ हैं और कुछ लगभग गेंदें\u000aहमें उन्हें संतुलित करने के लिए एक जादू का उपयोग करना होगा:\u000a‘जब तक हमारी पीठ न मुड़ जाए, तब तक वहीं रहो !''\u000aहम उन्हें संभालने के साथ अपनी उंगलियों को मोटे तौर पर पहनते हैं। ओह, बस एक और तरह का आउट - डोर गेम,\u000aएक तरफ. यह थोड़ा और अधिक आता है:\u000aवहाँ जहाँ यह है वहाँ हमें दीवार की आवश्यकता नहीं है:\u000aवह सब चीड़ है और मैं सेब का बगीचा हूँ. मेरे सेब के पेड़ कभी पार नहीं होंगे\u000aऔर उसकी चीड़ के नीचे शंकु खाओ, मैं उसे बताती हूँ. वह केवल यह कहता है, ‘अच्छी बाड़ें अच्छे पड़ोसी बनाती हैं।’\u000aवसंत मुझमें शरारत है, और मुझे आश्चर्य है\u000aअगर मैं उसके दिमाग में एक विचार डाल सकूँ:\u000a‘वे अच्छे पड़ोसी क्यों बनाते हैं? है ना\u000aगायें कहाँ हैं? लेकिन यहाँ कोई गाय नहीं है। दीवार बनाने से पहले मैं जानना चाहूंगी\u000aजो मैं अंदर या बाहर दीवार बना रही थी,\u000aऔर जिसे मैं अपमान देना चाहता था। कुछ ऐसा है जो दीवार को पसंद नहीं करता,\u000aवह इसे कम करना चाहता है।’ मैं उसे ‘एल्व्स‘ कह सकती थी,\u000aलेकिन यह वास्तव में कल्पित बौने नहीं हैं, और मैं इसके बजाय\u000aउसने यह खुद के लिए कहा था। मैं उसे वहाँ देखती हूँ\u000aऊपर से मजबूती से पकड़े गए पत्थर को लाना\u000aहर हाथ में, एक पुराने पत्थर के जंगली हथियार की तरह। वह अंधेरे में चलता है जैसा मुझे लगता है,\u000aकेवल जंगल और पेड़ों की छाया का नहीं। वह अपने पिता के कहने के पीछे नहीं जाएगा,\u000aऔर वह इसके बारे में इतनी अच्छी तरह से सोचना पसंद करता है\u000aवह फिर से कहता है, ‘अच्छी बाड़ें अच्छे पड़ोसी बनाती हैं।’'),'2026-10-28 12:10:14');
INSERT INTO translation_cache VALUES('4e15c75cf4460cc54237bbba21307e419ca7bcc70cf61cc2e780f8fa94d23fcf',unistr('Something there is that doesn’t love a wall,\u000aThat sends the frozen-ground-swell under it,\u000aAnd spills the upper boulders in the sun;\u000aAnd makes gaps even two can pass abreast.\u000aThe work of hunters is another thing:\u000aI have come after them and made repair\u000aWhere they have left not one stone on a stone,\u000aBut they would have the rabbit out of hiding,\u000aTo please the yelping dogs. The gaps I mean,\u000aNo one has seen them made or heard them made,\u000aBut at spring mending-time we find them there.\u000aI let my neighbor know beyond the hill;\u000aAnd on a day we meet to walk the line\u000aAnd set the wall between us once again.\u000aWe keep the wall between us as we go.\u000aTo each the boulders that have fallen to each.\u000aAnd some are loaves and some so nearly balls\u000aWe have to use a spell to make them balance:\u000a‘Stay where you are until our backs are turned!’\u000aWe wear our fingers rough with handling them.\u000aOh, just another kind of out-door game,\u000aOne on a side. It comes to little more:\u000aThere where it is we do not need the wall:\u000aHe is all pine and I am apple orchard.\u000aMy apple trees will never get across\u000aAnd eat the cones under his pines, I tell him.\u000aHe only says, ‘Good fences make good neighbors.’\u000aSpring is the mischief in me, and I wonder\u000aIf I could put a notion in his head:\u000a‘Why do they make good neighbors? Isn’t it\u000aWhere there are cows? But here there are no cows.\u000aBefore I built a wall I’d ask to know\u000aWhat I was walling in or walling out,\u000aAnd to whom I was like to give offense.\u000aSomething there is that doesn''t love a wall,\u000aThat wants it down.’ I could say ‘Elves’ to him,\u000aBut it’s not elves exactly, and I’d rather\u000aHe said it for himself. I see him there\u000aBringing a stone grasped firmly by the top\u000aIn each hand, like an old-stone savage armed.\u000aHe moves in darkness as it seems to me,\u000aNot of woods only and the shade of trees.\u000aHe will not go behind his father’s saying,\u000aAnd he likes having thought of it so well\u000aHe says again, ‘Good fences make good neighbors.’'),'ml',unistr('ഒരു മതിലിനെ ഇഷ്ടപ്പെടാത്ത എന്തോ ഒന്ന് ഉണ്ട്,\u000aഅതിനടിയിൽ ശീതീകരിച്ച നിലം-കിണർ അയയ്ക്കുന്നു,\u000aസൂര്യന്റെ ഉപരിതലത്തിൽ പാറകൾ വിതറുകയും ചെയ്യുന്നു;\u000aരണ്ടുപേർക്ക് പോലും കടന്നുപോകാൻ കഴിയുന്ന വിടവുകൾ ഉണ്ടാക്കുന്നു. വേട്ടക്കാരുടെ വേല മറ്റൊരു കാര്യമാണ്:\u000aഞാൻ അവരുടെ പിന്നാലെ ചെന്ന് അറ്റകുറ്റപ്പണി നടത്തി\u000aകല്ലിന്മേൽ ഒരു കല്ലുപോലും ശേഷിപ്പിക്കാതെ,\u000aഎന്നാൽ അവർ മുയലിനെ ഒളിപ്പിക്കും,\u000aയാചിക്കുന്ന നായ്ക്കളെ പ്രീതിപ്പെടുത്താൻ. ഞാൻ ഉദ്ദേശിക്കുന്ന വിടവുകൾ,\u000aഅവ ഉണ്ടാക്കിയതോ ഉണ്ടാക്കിയതോ ആരും കണ്ടിട്ടില്ല,\u000aഎന്നാൽ വസന്തകാലത്തെ അറ്റകുറ്റപ്പണി സമയത്ത് നാം അവയെ അവിടെ കണ്ടെത്തുന്നു. കുന്നിന് അപ്പുറം ഞാൻ എന്റെ അയൽക്കാരനെ അറിയിക്കുന്നു;\u000aഒരു ദിവസം ഞങ്ങൾ ലൈൻ നടക്കാൻ ഒത്തുചേരുന്നു\u000aഞങ്ങൾക്കിടയിൽ വീണ്ടും മതിൽ സ്ഥാപിക്കുക. നാം പോകുമ്പോൾ നാം നമുക്കിടയിൽ മതിൽ സൂക്ഷിക്കുന്നു. ഓരോരുത്തർക്കും വീണുകിടക്കുന്ന ഓരോ പാറകൾക്കും. ചിലത് അപ്പവും ചിലത് ഏകദേശം പന്തുകളുമാണ്\u000aഅവ സന്തുലിതമാക്കുന്നതിന് നാം ഒരു അക്ഷരപ്പിശക് ഉപയോഗിക്കേണ്ടതുണ്ട്:\u000a‘ഞങ്ങളുടെ പുറം തിരിഞ്ഞുപോകുന്നതുവരെ നിങ്ങൾ എവിടെയാണോ അവിടെത്തന്നെ തുടരുക!’\u000aഅവ കൈകാര്യം ചെയ്യുന്നതിൽ ഞങ്ങൾ വിരലുകൾ പരുക്കൻ ധരിക്കുന്നു. ഓ, മറ്റൊരു തരം ഔട്ട്-ഡോർ ഗെയിം,\u000aഒന്ന് ഒരു വശത്ത്. ഇത് അൽപ്പം കൂടുതലാണ്:\u000aഅവിടെ നമുക്ക് മതിലിന്റെ ആവശ്യമില്ല:\u000aഅവൻ എല്ലാം പൈൻ ആണ്, ഞാൻ ആപ്പിൾ തോട്ടമാണ്. എന്റെ ആപ്പിൾ മരങ്ങൾ ഒരിക്കലും വളരില്ല\u000aഅവന്റെ പൈനുകൾക്ക് കീഴിലുള്ള കോണുകൾ കഴിക്കുക, ഞാൻ അവനോട് പറയുന്നു. ‘നല്ല വേലികൾ നല്ല അയൽക്കാരെ ഉണ്ടാക്കുന്നു‘ എന്ന് മാത്രമേ അദ്ദേഹം പറയുന്നുള്ളൂ.\u000aവസന്തം എന്നിലെ കുഴപ്പമാണ്, ഞാൻ ആശ്ചര്യപ്പെടുന്നു\u000aഎനിക്ക് അവന്റെ തലയിൽ ഒരു ആശയം ഇടാൻ കഴിയുമെങ്കിൽ:\u000a‘എന്തുകൊണ്ടാണ് അവർ നല്ല അയൽക്കാരെ ഉണ്ടാക്കുന്നത്? അല്ലേ?\u000aപശുക്കൾ എവിടെയാണ്? എന്നാൽ ഇവിടെ പശുക്കളില്ല. ഞാൻ ഒരു മതിൽ പണിയുന്നതിനുമുമ്പ് ഞാൻ ചോദിക്കും\u000aഞാൻ മതിൽ കെട്ടുകയോ മതിൽ കെട്ടുകയോ ചെയ്യുകയായിരുന്നു,\u000aഞാൻ ആർക്കുവേണ്ടിയാണ് അപമാനിക്കാൻ ആഗ്രഹിച്ചത്. ഒരു മതിലിനെ ഇഷ്ടപ്പെടാത്ത എന്തോ ഒന്ന് ഉണ്ട്,\u000aഅതിന് അത് താഴേക്കിറങ്ങണം.’ എനിക്ക് അദ്ദേഹത്തോട് ‘എൽവ്സ്‘ എന്ന് പറയാൻ കഴിയും,\u000aഎന്നാൽ ഇത് കൃത്യമായി എൽവ്സ് അല്ല, ഞാൻ ഇഷ്ടപ്പെടുന്നു\u000aഅവൻ അത് സ്വയം പറഞ്ഞു. ഞാൻ അവനെ അവിടെ കാണുന്നു\u000aമുകളിൽ ഉറച്ചു പിടിച്ചിരിക്കുന്ന ഒരു കല്ല് കൊണ്ടുവരിക\u000aഓരോ കൈയിലും, ആയുധധാരിയായ ഒരു പഴയ കല്ലുപോലെ. എനിക്ക് തോന്നുന്നതുപോലെ അവൻ ഇരുട്ടിലേക്ക് നീങ്ങുന്നു,\u000aമരങ്ങൾ മാത്രമല്ല മരങ്ങളുടെ തണലും. അവൻ പിതാവിന്റെ വാക്കുകൾക്ക് പിറകിൽ പോകില്ല,\u000aഅതിനെക്കുറിച്ച് നന്നായി ചിന്തിക്കാൻ അവൻ ഇഷ്ടപ്പെടുന്നു\u000aഅദ്ദേഹം വീണ്ടും പറയുന്നു, ‘നല്ല വേലികൾ നല്ല അയൽക്കാരെ ഉണ്ടാക്കുന്നു.’'),'2026-10-28 12:10:59');
INSERT INTO translation_cache VALUES('1ab450dd68b7377a90bfc5d17c98027b9d14ae3083fe0f1c402e014bbfe9660f',unistr('Long, long ago there lived at the foot of the mountain a poor farmer and his aged, widowed mother. They owned a bit of land which supplied them with food and their humble lives were peaceful and happy.\u000a\u000aAt that time Shinano was governed by a despotic ruler who, though a brave warrior, had a great and cowardly shrinking from anything suggestive of fading health and strength. This caused him to send out a cruel proclamation. The entire province was given strict orders immediately to put to death all aged people.\u000a\u000aThose were barbarous days, and the custom of abandoning old people to die was not uncommon. However, it was not a law, and many of the helpless old lived as long as nature allowed in comfortable and welcome homes. The poor farmer loved his aged mother with tender reverence, and the order filled his heart with sorrow. But no one ever thought a second time about obeying the mandate of a daimio, so with many deep and hopeless sighs the youth prepared for what at that time was considered the kindest mode of death.\u000a\u000a\u000a\u000aJust at sundown, when his day’s work was ended, he took a quantity of the unwhitened rice which is the principal food of the poor, cooked and dried it, and tying it in a square of cloth he swung the bundle around his neck along with a gourd filled with cool, sweet water. Then he lifted his helpless old mother to his back and started on his painful journey up the mountain.\u000a\u000a\u000aThe road was long and steep. He plodded steadily on, the shadows growing deeper and deeper, until the moon, round and clear, rose above the mountain-top and peered pityingly through the branches upon the youth toiling onward, his head bent with weariness and his heart heavy with sorrow. The narrow road was crossed and recrossed by many paths made by hunters and wood-cutters. In some places they mingled in a confused puzzle, but he gave no heed. One path or another, it mattered not. On he went, climbing blindly upward—ever upward—toward the high, bare summit of what is now known as Obatsuyama, the mountain of the “Abandoning of the Aged.”\u000a\u000aThe eyes of the old mother were not so dim but that they noted the reckless hastening from one path to another, and her loving heart grew anxious. Her son did not know the mountain’s many paths, and his return might be one of danger, so she stretched forth her hand and snapping the twigs from the bushes as they passed, she quietly dropped a handful every few steps of the way, so as they climbed, the narrow path behind them was dotted at frequent intervals with tiny piles of twigs.\u000a\u000aAt last the summit was reached. Weary and heartsick, the youth gently released his burden and silently prepared a place of comfort, as his last duty to the loved one. Gathering fallen pine needles he made a soft cushion, and tenderly lifting his old mother thereon, he wrapped her padded coat more closely about the stooping shoulders and with tearful eyes and an aching heart said farewell.\u000a\u000aThe trembling mother voice was full of unselfish love as she gave her last injunction.\u000a\u000a“Let not thine eyes be blind, my son. The mountain road is full of danger. Look carefully and follow the path which holds the piles of twigs. They will guide thee to the familiar way farther down.”\u000a\u000aThe son’s surprised eyes looked back over the path, then at the poor old shrivelled hands all scratched and soiled by their work of love. His heart smote him and, bowing to the ground, he cried aloud:\u000a\u000a“Oh, Honourable Mother, thy kindness thrusts my heart! I will not leave thee. Together we will follow the path of twigs, and together we will die!”\u000a\u000aOnce more he shouldered his burden (how light it seemed now!) and hastened down the path, through the shadows and the moonlight, to the little hut in the valley.\u000a\u000aBeneath the kitchen floor was a walled closet for food, which was covered over and hidden from view. There the son hid his mother, supplying her with everything needful and continually watching and fearing.\u000a\u000aTime passed and he was beginning to feel safe, when again the despot sent forth heralds bearing an unreasonable and useless order; seemingly as a boast of his power. His demand was that his subjects should present him with a rope of ashes. The entire province trembled with dread. The order must be obeyed; yet who in all Shinano could make a rope of ashes?\u000a\u000a\u000a\u000aOne night, in great distress, the son whispered the news to his hidden mother.\u000a\u000a“Wait!” she said, “I will think.”\u000a\u000aOn the second day she told him what to do.\u000a\u000a“Make a rope of twisted straw,” she said, “then stretch it upon a row of flat stones and burn it there on a windless night.”\u000a\u000aHe called the people together and did as she said, and when the blaze had died, behold, upon the stones, with every twist and fibre showing perfect, lay a rope of whitened ashes.\u000a\u000aThe daimio was pleased at the wit of the youth, and praised him greatly, but demanded to know where he had obtained his wisdom.\u000a\u000a“Alas! Alas!” cried the farmer, “the truth must be told!” and with many deep bows he related his story.\u000a\u000aThe daimio listened, then meditated in silence. Finally he lifted his head.\u000a\u000a“Shinano needs more than the strength of youth,” he said gravely. “Ah, that I should have forgotten the well-known saying, ‘With the crown of snow, there cometh wisdom!’”\u000a\u000aThat very hour the cruel law was abolished, and the custom drifted into so far a past that only the legend remains.\u000a\u000a\u000a\u000aThe Aged Mother was featured as The Short Story of the Day on Sun, May 10, 2026\u000aSource: Etsu Inagaki Sugimoto, A Daughter of the Samurai (Doubleday, Page & Company, 1925), chapter “My First Journey,” pp. 101–104.\u000a\u000aThis story is featured in our collection of Short Short Stories and Short Stories for Middle School II. If you wish to explore more literature from Japan you may wish to read from our library of Japanese Fairy Tales.'),'hi',unistr('बहुत समय पहले, पहाड़ के नीचे एक गरीब किसान और उसकी वृद्ध, विधवा माँ रहती थी। उनके पास थोड़ी सी जमीन थी जो उन्हें भोजन प्रदान करती थी और उनका विनम्र जीवन शांतिपूर्ण और खुशहाल था। उस समय शिनानो एक निरंकुश शासक द्वारा शासित था, जो एक बहादुर योद्धा होने के बावजूद, स्वास्थ्य और ताकत को कम करने के सुझाव देने वाली किसी भी चीज से एक महान और कायरतापूर्ण सिकुड़ रहा था। इसने उसे एक क्रूर उद्घोषणा भेजी। पूरे प्रांत को सभी वृद्ध लोगों को मारने के लिए तुरंत सख्त आदेश दिए गए थे। वे बर्बर दिन थे, और बूढ़े लोगों को मरने के लिए छोड़ने का रिवाज असामान्य नहीं था। हालांकि, यह एक कानून नहीं था, और कई असहाय बूढ़े तब तक रहते थे जब तक प्रकृति ने आरामदायक और स्वागत योग्य घरों में रहने की अनुमति दी। गरीब किसान अपनी वृद्ध माँ से कोमल श्रद्धा के साथ प्यार करता था, और इस आदेश ने उसके दिल को दुःख से भर दिया। लेकिन किसी ने कभी भी डेमियो के जनादेश का पालन करने के बारे में दूसरी बार नहीं सोचा, इसलिए कई गहरी और निराशाजनक आहों के साथ युवाओं ने उस समय के लिए तैयार किया जिसे मृत्यु का सबसे दयालु तरीका माना जाता था। बस सूर्यास्त के समय, जब उसका दिन का काम समाप्त हो गया, तो उसने गरीबों का मुख्य भोजन, बिना सफ़ेद चावल की एक मात्रा ली, उसे पकाया और सुखाया, और कपड़े के एक वर्ग में बांधकर उसने अपनी गर्दन के चारों ओर पोटली को ठंडे, मीठे पानी से भरे लौकी के साथ घुमाया। फिर उसने अपनी असहाय बूढ़ी माँ को अपनी पीठ पर उठाया और पहाड़ पर अपनी दर्दनाक यात्रा शुरू की। सड़क लंबी और खड़ी थी। वह लगातार आगे बढ़ रहा था, जब तक कि चंद्रमा, गोलाकार और स्पष्ट नहीं हो जाता, तब तक छाया गहरी और गहरी हो जाती है, पहाड़ की चोटी से ऊपर उठती है और युवाओं के ऊपर शाखाओं के माध्यम से दयालुता से झांकती है, उसका सिर थकावट से झुकता है और उसका दिल दुख से भारी होता है। संकीर्ण सड़क को शिकारी और लकड़ी काटने वालों द्वारा बनाए गए कई रास्तों से पार किया गया था। कुछ जगहों पर वे एक भ्रमित पहेली में घुलमिल गए, लेकिन उसने कोई ध्यान नहीं दिया। एक रास्ता या दूसरा, इससे कोई फर्क नहीं पड़ता। वह आँख बंद करके ऊपर की ओर चढ़ रहा था - कभी ऊपर की ओर - जो अब ओबत्सुयामा के रूप में जाना जाता है, जो "वृद्धों का त्याग" का पहाड़ है।\u000a बूढ़ी माँ की आँखें इतनी धुँधली नहीं थीं, लेकिन उन्होंने एक रास्ते से दूसरे रास्ते की लापरवाही पर ध्यान दिया, और उसका प्यार भरा दिल चिंतित हो गया। उसका बेटा पहाड़ के कई रास्तों को नहीं जानता था, और उसकी वापसी खतरे में पड़ सकती थी, इसलिए उसने अपना हाथ आगे बढ़ाया और झाड़ियों से टहनियों को खींचते हुए जाते हुए, उसने चुपचाप रास्ते के हर कुछ कदमों पर एक मुट्ठी गिरा दी, इसलिए जैसे ही वे चढ़े, उनके पीछे का संकीर्ण रास्ता टहनियों के छोटे ढेर के साथ लगातार अंतराल पर बिखरा हुआ था। अंत में शिखर तक पहुँच गया था। थके हुए और थके हुए, युवा ने धीरे से अपना बोझ छोड़ दिया और चुपचाप अपने प्रियजन के लिए अपने अंतिम कर्तव्य के रूप में आराम की जगह तैयार की। गिरी हुई चीड़ की सुइयों को इकट्ठा करते हुए उसने एक नरम तकिया बनाया, और उस पर अपनी बूढ़ी माँ को कोमलता से उठाते हुए, उसने अपने गद्देदार कोट को झुके हुए कंधों के बारे में और अधिक बारीकी से लपेटा और आँसू भरी आंखों के साथ और एक दर्दनाक दिल ने अलविदा कहा। कांपती माँ की आवाज़ निस्वार्थ प्रेम से भरी थी क्योंकि उसने अपना अंतिम निषेधाज्ञा दे दी थी। “हे मेरे पुत्र, तेरी आंखें अन्धी न रहें। पहाड़ी सड़क खतरे से भरी हुई है। ध्यान से देखें और उस पथ का अनुसरण करें जिसमें टहनियों के ढेर हैं। वे तुझे जाने - पहचाने मार्ग पर ले चलेंगे।”\u000a बेटे की आश्चर्यचकित आँखों ने रास्ते की ओर देखा, फिर बेचारे बूढ़े हिलते हुए हाथों की ओर देखा, सभी खरोंच और उनके प्यार के काम से गंदे हो गए। उसके दिल ने उसे मारा और जमीन पर झुककर, वह जोर से चिल्लाया: "ओह, आदरणीय माँ, आपकी दयालुता मेरे दिल को धक्का देती है! मैं तुम्हें नहीं छोड़ूंगी। हम एक साथ टहनियों के रास्ते पर चलेंगे, और हम एक साथ मरेंगे !"\u000a एक बार फिर उसने अपना बोझ कंधे पर उठाया (अब यह कितना हल्का लग रहा था!) और घाटी में छोटी झोपड़ी तक, छाया और चांदनी के माध्यम से, रास्ते में तेज़ी से नीचे उतरा। रसोई के फर्श के नीचे भोजन के लिए एक दीवार वाली अलमारी थी, जो ऊपर से ढकी हुई थी और दृश्य से छिपी हुई थी। वहाँ बेटे ने अपनी माँ को छिपाया, उसे सब कुछ ज़रूरतमंदों के साथ आपूर्ति की और लगातार देखता और डरता रहा। समय बीतता गया और वह सुरक्षित महसूस करने लगा था, जब फिर से निरंकुश ने एक अनुचित और बेकार आदेश वाले संदेशवाहक भेजे; प्रतीत होता है कि वह अपनी शक्ति के घमंड के रूप में था। उनकी मांग थी कि उनकी प्रजा उन्हें राख की रस्सी के साथ पेश करे। पूरा प्रांत डर से कांप उठा। आदेश का पालन किया जाना चाहिए; फिर भी सभी शिनानो में से कौन राख की रस्सी बना सकता है? एक रात, बहुत परेशान होकर, बेटे ने अपनी छिपी हुई माँ को यह खबर सुनाई। "रुको !" उसने कहा," मैं सोचूंगी। "\u000a दूसरे दिन उसने उसे बताया कि क्या करना है। "मुड़े हुए पुआल की एक रस्सी बनाओ ," उसने कहा," फिर इसे चपटे पत्थरों की एक पंक्ति पर फैलाएं और बिना हवा के रात को वहां जला दें। " उसने लोगों को एक साथ बुलाया और जैसा उसने कहा था वैसा ही किया, और जब आग मर गई, तो देखो, पत्थरों पर, हर एक मोड़ और रेशे से परिपूर्ण होकर, सफ़ेद राख की एक रस्सी बिछा दी। डेमियो युवक की बुद्धि से प्रसन्न था, और उसने उसकी बहुत प्रशंसा की, लेकिन यह जानने की मांग की कि उसने अपनी बुद्धि कहाँ से प्राप्त की है। "हाय! हाय !" किसान चिल्लाया," सच कहा जाना चाहिए !" और उसने कई गहरी धनुषों के साथ अपनी कहानी सुनाई। डेमियो ने सुना, फिर चुपचाप ध्यान किया। अंत में उसने अपना सिर उठाया। "शिनानो को युवाओं की ताकत से ज्यादा की जरूरत है ," उन्होंने गंभीरता से कहा। "आह, मुझे यह प्रसिद्ध कहावत भूल जाना चाहिए था, ‘बर्फ के मुकुट के साथ, बुद्धि आती है !''"\u000a उसी समय क्रूर कानून को समाप्त कर दिया गया, और रिवाज अब तक एक ऐसे अतीत में चला गया कि केवल किंवदंती बनी हुई है। वृद्ध माँ को सूर्य पर दिन की लघु कहानी के रूप में चित्रित किया गया था, 10 मई, 2026\u000aस्रोत: Etsu Inagaki Sugimoto, समुराई की एक बेटी (डबलडे, पेज एंड कंपनी, 1925), अध्याय "मेरी पहली यात्रा ," पृष्ठ 101 -104। यह कहानी मिडिल स्कूल II के लिए लघु लघु कहानियों और लघु कहानियों के हमारे संग्रह में चित्रित की गई है। यदि आप जापान से अधिक साहित्य का पता लगाना चाहते हैं तो आप जापानी परी कथाओं की हमारी लाइब्रेरी से पढ़ना चाह सकते हैं।'),'2026-10-28 22:08:01');
INSERT INTO translation_cache VALUES('2ba01c300cd4dd570cde3f92bc720a48ef6020702b563504e59f220eba862f27',unistr('Long, long ago there lived at the foot of the mountain a poor farmer and his aged, widowed mother. They owned a bit of land which supplied them with food and their humble lives were peaceful and happy.\u000a\u000aAt that time Shinano was governed by a despotic ruler who, though a brave warrior, had a great and cowardly shrinking from anything suggestive of fading health and strength. This caused him to send out a cruel proclamation. The entire province was given strict orders immediately to put to death all aged people.\u000a\u000aThose were barbarous days, and the custom of abandoning old people to die was not uncommon. However, it was not a law, and many of the helpless old lived as long as nature allowed in comfortable and welcome homes. The poor farmer loved his aged mother with tender reverence, and the order filled his heart with sorrow. But no one ever thought a second time about obeying the mandate of a daimio, so with many deep and hopeless sighs the youth prepared for what at that time was considered the kindest mode of death.\u000a\u000a\u000a\u000aJust at sundown, when his day’s work was ended, he took a quantity of the unwhitened rice which is the principal food of the poor, cooked and dried it, and tying it in a square of cloth he swung the bundle around his neck along with a gourd filled with cool, sweet water. Then he lifted his helpless old mother to his back and started on his painful journey up the mountain.\u000a\u000a\u000aThe road was long and steep. He plodded steadily on, the shadows growing deeper and deeper, until the moon, round and clear, rose above the mountain-top and peered pityingly through the branches upon the youth toiling onward, his head bent with weariness and his heart heavy with sorrow. The narrow road was crossed and recrossed by many paths made by hunters and wood-cutters. In some places they mingled in a confused puzzle, but he gave no heed. One path or another, it mattered not. On he went, climbing blindly upward—ever upward—toward the high, bare summit of what is now known as Obatsuyama, the mountain of the “Abandoning of the Aged.”\u000a\u000aThe eyes of the old mother were not so dim but that they noted the reckless hastening from one path to another, and her loving heart grew anxious. Her son did not know the mountain’s many paths, and his return might be one of danger, so she stretched forth her hand and snapping the twigs from the bushes as they passed, she quietly dropped a handful every few steps of the way, so as they climbed, the narrow path behind them was dotted at frequent intervals with tiny piles of twigs.\u000a\u000aAt last the summit was reached. Weary and heartsick, the youth gently released his burden and silently prepared a place of comfort, as his last duty to the loved one. Gathering fallen pine needles he made a soft cushion, and tenderly lifting his old mother thereon, he wrapped her padded coat more closely about the stooping shoulders and with tearful eyes and an aching heart said farewell.\u000a\u000aThe trembling mother voice was full of unselfish love as she gave her last injunction.\u000a\u000a“Let not thine eyes be blind, my son. The mountain road is full of danger. Look carefully and follow the path which holds the piles of twigs. They will guide thee to the familiar way farther down.”\u000a\u000aThe son’s surprised eyes looked back over the path, then at the poor old shrivelled hands all scratched and soiled by their work of love. His heart smote him and, bowing to the ground, he cried aloud:\u000a\u000a“Oh, Honourable Mother, thy kindness thrusts my heart! I will not leave thee. Together we will follow the path of twigs, and together we will die!”\u000a\u000aOnce more he shouldered his burden (how light it seemed now!) and hastened down the path, through the shadows and the moonlight, to the little hut in the valley.\u000a\u000aBeneath the kitchen floor was a walled closet for food, which was covered over and hidden from view. There the son hid his mother, supplying her with everything needful and continually watching and fearing.\u000a\u000aTime passed and he was beginning to feel safe, when again the despot sent forth heralds bearing an unreasonable and useless order; seemingly as a boast of his power. His demand was that his subjects should present him with a rope of ashes. The entire province trembled with dread. The order must be obeyed; yet who in all Shinano could make a rope of ashes?\u000a\u000a\u000a\u000aOne night, in great distress, the son whispered the news to his hidden mother.\u000a\u000a“Wait!” she said, “I will think.”\u000a\u000aOn the second day she told him what to do.\u000a\u000a“Make a rope of twisted straw,” she said, “then stretch it upon a row of flat stones and burn it there on a windless night.”\u000a\u000aHe called the people together and did as she said, and when the blaze had died, behold, upon the stones, with every twist and fibre showing perfect, lay a rope of whitened ashes.\u000a\u000aThe daimio was pleased at the wit of the youth, and praised him greatly, but demanded to know where he had obtained his wisdom.\u000a\u000a“Alas! Alas!” cried the farmer, “the truth must be told!” and with many deep bows he related his story.\u000a\u000aThe daimio listened, then meditated in silence. Finally he lifted his head.\u000a\u000a“Shinano needs more than the strength of youth,” he said gravely. “Ah, that I should have forgotten the well-known saying, ‘With the crown of snow, there cometh wisdom!’”\u000a\u000aThat very hour the cruel law was abolished, and the custom drifted into so far a past that only the legend remains.\u000a\u000a\u000a\u000aThe Aged Mother was featured as The Short Story of the Day on Sun, May 10, 2026\u000aSource: Etsu Inagaki Sugimoto, A Daughter of the Samurai (Doubleday, Page & Company, 1925), chapter “My First Journey,” pp. 101–104.\u000a\u000aThis story is featured in our collection of Short Short Stories and Short Stories for Middle School II. If you wish to explore more literature from Japan you may wish to read from our library of Japanese Fairy Tales.'),'ml',unistr('വളരെക്കാലം മുമ്പ്, പർവതത്തിന്റെ ചുവട്ടിൽ ഒരു ദരിദ്രനായ കൃഷിക്കാരനും പ്രായമായ വിധവയായ അമ്മയും താമസിച്ചിരുന്നു. അവർക്ക് ഭക്ഷണം നൽകുന്ന ഒരു ചെറിയ സ്ഥലം അവരുടെ കൈവശമുണ്ടായിരുന്നു, അവരുടെ എളിയ ജീവിതം സമാധാനപരവും സന്തുഷ്ടവുമായിരുന്നു. അക്കാലത്ത് ഷിനാനോയെ ഭരിച്ചത് ഒരു സ്വേച്ഛാധിപത്യ ഭരണാധികാരിയായിരുന്നു, ധീരനായ യോദ്ധാവാണെങ്കിലും, ആരോഗ്യവും ശക്തിയും മങ്ങുന്നതായി സൂചിപ്പിക്കുന്ന ഒന്നിൽ നിന്നും വലിയതും ഭീരുത്വപരവുമായ ഒരു ചുരുങ്ങൽ ഉണ്ടായിരുന്നു. ഇത് ക്രൂരമായ ഒരു വിളംബരം അയയ്ക്കാൻ അവനെ പ്രേരിപ്പിച്ചു. എല്ലാ പ്രായമായവരെയും വധിക്കാൻ മുഴുവൻ പ്രവിശ്യയ്ക്കും ഉടൻ കർശനമായ ഉത്തരവുകൾ നൽകി. ആ ദിവസങ്ങൾ ക്രൂരമായിരുന്നു, വൃദ്ധരെ മരിക്കാൻ വിട്ടുകൊടുക്കുന്ന ആചാരം അസാധാരണമല്ലായിരുന്നു. എന്നിരുന്നാലും, ഇത് ഒരു നിയമമായിരുന്നില്ല, നിസ്സഹായരായ വൃദ്ധരിൽ പലരും പ്രകൃതി സൗകര്യപ്രദവും സ്വാഗതാർഹവുമായ ഭവനങ്ങളിൽ അനുവദിക്കുന്നിടത്തോളം കാലം ജീവിച്ചിരുന്നു. ദരിദ്രനായ കൃഷിക്കാരൻ തന്റെ വൃദ്ധയായ അമ്മയെ ആർദ്രമായ ഭക്തിയോടെ സ്നേഹിച്ചു, ആ ക്രമം അവന്റെ ഹൃദയത്തിൽ ദുഃഖം നിറച്ചു. എന്നാൽ ഒരു ഡൈമിയോയുടെ കല്പന അനുസരിക്കുന്നതിനെക്കുറിച്ച് ആരും രണ്ടാമതൊരിക്കലും ചിന്തിച്ചിട്ടില്ല, അതിനാൽ അക്കാലത്ത് ഏറ്റവും ദയനീയമായ മരണ രീതിയായി കണക്കാക്കപ്പെട്ടിരുന്ന കാര്യത്തിനായി യുവാക്കൾ അഗാധവും നിരാശാജനകവുമായ നെടുവീർപ്പുകളോടെ തയ്യാറായി. സൂര്യാസ്തമയസമയത്ത്, തന്റെ പകൽ ജോലി അവസാനിച്ചപ്പോൾ, ദരിദ്രരുടെ പ്രധാന ഭക്ഷണമായ വെണ്ണയില്ലാത്ത അരിയുടെ ഒരു അളവ് എടുത്ത് പാകം ചെയ്ത് ഉണക്കി, ഒരു ചതുരശ്ര തുണിയിൽ കെട്ടിയിട്ട് തണുത്തതും മധുരമുള്ളതുമായ വെള്ളം നിറച്ച ഒരു പാത്രവും കഴുത്തിൽ ചുറ്റി. പിന്നെ അവൻ തന്റെ നിസ്സഹായയായ വൃദ്ധയായ അമ്മയെ പുറകിലേക്ക് ഉയർത്തി പർവതത്തിലേക്കുള്ള വേദനാജനകമായ യാത്ര ആരംഭിച്ചു. റോഡ് നീളമുള്ളതും കുത്തനെയുള്ളതുമായിരുന്നു. ചന്ദ്രൻ, വൃത്താകൃതിയിലും വ്യക്തമായും, പർവതശിഖരത്തിന് മുകളിലൂടെ ഉയർന്നുവന്ന് യുവാക്കൾ അധ്വാനിക്കുന്നതിന്റെ മേലുള്ള ശാഖകളിലൂടെ സഹതാപത്തോടെ കടന്നുപോകുന്നതുവരെ, നിഴലുകൾ കൂടുതൽ ആഴത്തിലും ആഴത്തിലും വളരുന്നതുവരെ അദ്ദേഹം നിരന്തരം ഉഴുതുമറിച്ചു. ഇടുങ്ങിയ റോഡ് വേട്ടക്കാരും മരം മുറിക്കുന്നവരും ഉണ്ടാക്കിയ നിരവധി പാതകളിലൂടെ കടന്നുപോയി. ചില സ്ഥലങ്ങളിൽ അവർ ആശയക്കുഴപ്പത്തിൽ കലർന്നിരുന്നു, പക്ഷേ അവൻ ശ്രദ്ധിച്ചില്ല. ഒരു പാതയോ മറ്റോ, അതിൽ കാര്യമില്ല. അദ്ദേഹം മുന്നോട്ട് പോയി, അന്ധമായി മുകളിലേക്ക്-എപ്പോഴും മുകളിലേക്കും മുകളിലേക്കും-ഇപ്പോൾ ഒബാറ്റ്സുയാമ എന്നറിയപ്പെടുന്ന "പ്രായമായവരെ ഉപേക്ഷിക്കൽ" എന്ന പർവതത്തിന്റെ നഗ്നമായ ഉച്ചകോടിയിലേക്കും.\u000a വൃദ്ധയായ അമ്മയുടെ കണ്ണുകൾ അത്ര മങ്ങിയതായിരുന്നില്ല, എന്നാൽ അശ്രദ്ധമായി ഒരു പാതയിൽ നിന്ന് മറ്റൊന്നിലേക്ക് തിരിയുന്നത് അവർ ശ്രദ്ധിക്കുകയും അവളുടെ സ്നേഹനിധിയായ ഹൃദയം ഉത്കണ്ഠാകുലമായി വളരുകയും ചെയ്തു. അവളുടെ മകന് പർവതത്തിന്റെ പല വഴികളും അറിയില്ലായിരുന്നു, അവന്റെ മടങ്ങിവരവ് അപകടകരമാകാം, അതിനാൽ അവൾ കൈ നീട്ടി കുറ്റിക്കാട്ടിൽ നിന്ന് കൊമ്പുകൾ കടത്തിക്കൊണ്ട് അവർ കടന്നുപോകുമ്പോൾ, അവർ കയറിയതുപോലെ, അവരുടെ പിന്നിലുള്ള ഇടുങ്ങിയ പാത ഇടയ്ക്കിടെ ചെറിയ കൊമ്പുകളുള്ള ഇടവേളകളിൽ കുത്തനെയുള്ളതായിരിക്കും. ഒടുവിൽ ഉച്ചകോടിയിലെത്തി. ക്ഷീണിതനും ഹൃദയഭാരമുള്ളവനുമായ യുവാവ് തന്റെ ഭാരം സാവധാനം പുറത്തെടുക്കുകയും പ്രിയപ്പെട്ടവരോടുള്ള അവസാന കടമയായി നിശബ്ദമായി ആശ്വാസകരമായ ഒരു സ്ഥലം തയ്യാറാക്കുകയും ചെയ്തു. വീണുകിടക്കുന്ന പൈൻ സൂചികൾ ശേഖരിച്ച് അയാൾ ഒരു മൃദുവായ തലയണ ഉണ്ടാക്കി, അതിൽ തന്റെ വൃദ്ധയായ അമ്മയെ മൃദുവായി ഉയർത്തി, കുനിഞ്ഞിരിക്കുന്ന തോളുകളെക്കുറിച്ചും കണ്ണുനീർ നിറഞ്ഞ കണ്ണുകളോടെയും അവളുടെ പാഡ് കോട്ട് കൂടുതൽ സൂക്ഷ്മമായി പൊതിഞ്ഞു, വേദനാജനകമായ ഒരു ഹൃദയം വിട പറഞ്ഞു. വിറയാർന്ന അമ്മയുടെ സ്വരം നിസ്വാർത്ഥമായ സ്നേഹത്താൽ നിറഞ്ഞിരുന്നു, അവൾ അവസാന നിർദേശം നൽകി. “മകനേ, നിന്റെ കണ്ണുകൾ അന്ധമായിരിക്കരുത്. പർവത പാത അപകടസാധ്യത നിറഞ്ഞതാണ്. ശ്രദ്ധാപൂർവ്വം നോക്കുക, കൊമ്പുകളുടെ കൂമ്പാരം പിടിക്കുന്ന പാത പിന്തുടരുക. അവർ നിങ്ങളെ കൂടുതൽ പരിചിതമായ വഴിയിലേക്ക് നയിക്കും.”\u000a മകന്റെ ആശ്ചര്യകരമായ കണ്ണുകൾ പാതയിലൂടെ തിരിഞ്ഞുനോക്കി, തുടർന്ന് ദരിദ്രരായ വൃദ്ധരുടെ കൈകളെല്ലാം അവരുടെ സ്നേഹപ്രവൃത്തിയിൽ മാന്തികുഴിയുണ്ടാക്കുകയും മലിനമാക്കുകയും ചെയ്തു. അവന്റെ ഹൃദയം അവനെ അടിച്ചു നിലത്തുവീണ് ഉറക്കെ നിലവിളിച്ചു: “ഓ, മാന്യമായ മാതാവേ, അങ്ങയുടെ കാരുണ്യം എന്റെ ഹൃദയത്തെ സ്പർശിക്കുന്നു! ഞാൻ നിന്നെ ഉപേക്ഷിക്കുകയില്ല. ഒരുമിച്ചു നാം കൊമ്പുകളുടെ പാത പിന്തുടരും, ഒരുമിച്ചു നാം മരിക്കും!”\u000a ഒരിക്കൽക്കൂടി അവൻ തന്റെ ഭാരം ചുമന്ന് (ഇപ്പോൾ എത്ര നേരിയതായി തോന്നുന്നു!), നിഴലുകളിലൂടെയും ചന്ദ്രപ്രകാശത്തിലൂടെയും താഴ്‌വരയിലെ ചെറിയ കുടിലിലേക്ക് കുതിച്ചുചാടി. അടുക്കള തറയുടെ ചുവടെ ഭക്ഷണത്തിനായി ഒരു മതിലുള്ള ക്ലോസറ്റ് ഉണ്ടായിരുന്നു, അത് മൂടി കാഴ്ചയിൽ നിന്ന് മറച്ചിരുന്നു. അവിടെ മകൻ അമ്മയെ ഒളിപ്പിക്കുകയും ആവശ്യമായതും നിരന്തരം ശ്രദ്ധിക്കുകയും ഭയപ്പെടുകയും ചെയ്യുന്നതെല്ലാം അവൾക്ക് നൽകുകയും ചെയ്തു. കാലം കടന്നുപോയി, അവന് സുരക്ഷിതത്വം അനുഭവപ്പെടാൻ തുടങ്ങി, യുക്തിരഹിതവും ഉപയോഗശൂന്യവുമായ ഒരു ക്രമം ചുമന്നുകൊണ്ട് വീണ്ടും നിന്ദകൻ വിളംബരക്കാരെ അയച്ചു; പ്രത്യക്ഷത്തിൽ അവന്റെ ശക്തിയുടെ പ്രശംസപോലെ. അവന്റെ പ്രജകൾ അവനെ ചാരത്തിന്റെ ഒരു കയറിൽ അവതരിപ്പിക്കണമെന്നായിരുന്നു അവന്റെ ആവശ്യം. പ്രവിശ്യ മുഴുവൻ ഭയത്താൽ വിറച്ചു. ഉത്തരവ് അനുസരിക്കേണ്ടതാണ്; എന്നിട്ടും എല്ലാ ഷിനാനോയിലും ചാരം കൊണ്ടുള്ള ഒരു കയർ ഉണ്ടാക്കാൻ ആർക്കാണ് കഴിയുക? ഒരു രാത്രി, വലിയ ദുരിതത്തിൽ, മകൻ തന്റെ മറഞ്ഞിരിക്കുന്ന അമ്മയോട് ഈ വാർത്ത മന്ത്രിച്ചു. "നിൽക്കൂ!" അവൾ പറഞ്ഞു, "ഞാൻ ചിന്തിക്കാം."\u000a രണ്ടാം ദിവസം അവൾ എന്താണ് ചെയ്യേണ്ടതെന്ന് അവനോട് പറഞ്ഞു. "വളച്ചൊടിച്ച വൈക്കോൽ കൊണ്ട് ഒരു കയർ ഉണ്ടാക്കുക," അവൾ പറഞ്ഞു, "എന്നിട്ട് അതിനെ പരന്ന കല്ലുകളുടെ ഒരു നിരയിൽ നീട്ടി കാറ്റില്ലാത്ത രാത്രിയിൽ അവിടെ കത്തിക്കുക." അവൻ ജനങ്ങളെ ഒന്നിച്ചുകൂട്ടി, അവൾ പറഞ്ഞതുപോലെ ചെയ്തു, തീജ്വാല ചത്തപ്പോൾ, കല്ലുകളിൽ, ഓരോ വളച്ചൊടിയും നാരുകളും തികഞ്ഞതായി കാണപ്പെടുന്ന ഒരു ചാരത്തിന്റെ കയറു കിടക്കുന്നതു കണ്ടു. യുവാക്കളുടെ ബുദ്ധിയിൽ ഡൈമിയോ സന്തോഷിക്കുകയും, അവനെ വളരെയധികം പ്രശംസിക്കുകയും ചെയ്തു, എന്നാൽ അവൻ തന്റെ ജ്ഞാനം എവിടെ നിന്നാണ് നേടിയതെന്ന് അറിയാൻ ആവശ്യപ്പെട്ടു. “അയ്യോ! കഷ്ടം!” കർഷകൻ നിലവിളിച്ചു, “സത്യം പറയണം!” അനേകം വില്ലുകളാൽ അവൻ തന്റെ കഥ വിവരിച്ചു. ഡൈമിയോ ശ്രദ്ധിച്ചു, തുടർന്ന് നിശബ്ദമായി ധ്യാനിച്ചു. ഒടുവിൽ അവൻ തല ഉയർത്തി. "ഷിനാനോയ്ക്ക് യുവാക്കളുടെ ശക്തിയേക്കാൾ കൂടുതൽ ആവശ്യമാണ്," അദ്ദേഹം ഗൗരവത്തോടെ പറഞ്ഞു. “അയ്യോ, ''മഞ്ഞിന്റെ കിരീടത്തോടുകൂടെ ജ്ഞാനം വരുന്നു‘ എന്ന പ്രസിദ്ധമായ ചൊല്ലു ഞാൻ മറന്നിരുന്നെങ്കിൽ!”\u000a ആ മണിക്കൂറിലാണ് ക്രൂരമായ നിയമം നിർത്തലാക്കപ്പെട്ടത്, ആചാരം ഇതുവരെയുള്ള ഒരു ഭൂതകാലത്തിലേക്ക് നീങ്ങി, ഇതിഹാസം മാത്രം അവശേഷിക്കുന്നു. ദി ഏജ്ഡ് മദർ 2026 മെയ് 10 ന് ദി ഷോർട്ട് സ്റ്റോറി ഓഫ് ദി ഡേ ഓൺ സൺ എന്ന പേരിൽ അവതരിപ്പിച്ചു\u000aSource: Etsu Inagaki Sugimoto, A Daughter of the Samurai (Doubleday, Page & Company, 1925), Chapter “My First Journey,” pp. 101–104. മിഡിൽ സ്കൂൾ II-നുള്ള ഞങ്ങളുടെ ചെറുകഥകളുടെയും ചെറുകഥകളുടെയും സമാഹാരത്തിലാണ് ഈ കഥ അവതരിപ്പിച്ചിരിക്കുന്നത്. ജപ്പാനിൽ നിന്നുള്ള കൂടുതൽ സാഹിത്യങ്ങൾ പര്യവേക്ഷണം ചെയ്യാൻ നിങ്ങൾ ആഗ്രഹിക്കുന്നുവെങ്കിൽ, ഞങ്ങളുടെ ജാപ്പനീസ് ഫെയറി ടെയിൽസ് ലൈബ്രറിയിൽ നിന്ന് വായിക്കാൻ നിങ്ങൾ ആഗ്രഹിച്ചേക്കാം.'),'2026-10-28 22:08:19');
