INSERT INTO session_activities VALUES(105,'a0a8d727-a897-47b5-8836-b50d08e60592','ANALYZE',unistr('Whose woods these are I think I know.   \u000aHis house is in the village though;   \u000aHe will not see me stopping here   \u000aTo watch his woods fill up with snow.   \u000a\u000aMy little horse must think it queer   \u000aTo stop without a farmhouse near   \u000aBetween the woods and frozen lake   \u000aThe darkest evening of the year.   \u000a\u000aHe gives his harness bells a shake   \u000aTo ask if there is some mistake.   \u000aThe only other sound’s the sweep   \u000aOf easy wind and downy flake.   \u000a\u000aThe woods are lovely, dark and deep,   \u000aBut I have promises to keep,   \u000aAnd miles to go before I sleep,   \u000aAnd miles to go before I sleep.\u000a'),'108 words, 6 sentences','{"sourceName":"Manuscript","wordCount":108}','2026-10-28 11:25:22');
