INSERT INTO session_activities VALUES(108,'a0a8d727-a897-47b5-8836-b50d08e60592','TRANSLATE',unistr('Whose woods these are I think I know.   \u000aHis house is in the village though;   \u000aHe will not see me stopping here   \u000aTo watch his woods fill up with snow.   \u000a\u000aMy little horse must think it queer   \u000aTo stop without a farmhouse near   \u000aBetween the woods and frozen lake   \u000aThe darkest evening of the year.   \u000a\u000aHe gives his harness bells a shake   \u000aTo ask if there is some mistake.   \u000aThe only other sound’s the sweep   \u000aOf easy wind and downy flake.   \u000a\u000aThe woods are lovely, dark and deep,   \u000aBut I have promises to keep,   \u000aAnd miles to go before I sleep,   \u000aAnd miles to go before I sleep.'),unistr('मुझे लगता है कि ये किसके जंगल हैं. हालांकि उसका घर गाँव में है;   \u000aवह मुझे यहाँ रुकते हुए नहीं देखेगा   \u000aउसके जंगल को बर्फ से भरते हुए देखने के लिए। मेरे छोटे घोड़े को यह अजीब लगता होगा   \u000aपास में फ़ार्महाउस के बिना रुकना   \u000aजंगल और जमे हुए झील के बीच   \u000aसाल की सबसे अंधेरी शाम। वह अपनी हार्नेस की घंटी को एक हिला देता है   \u000aयह पूछने के लिए कि क्या कोई गलती है। एकमात्र अन्य ध्वनि स्वीप है   \u000aआसान हवा और डाउनी फ्लेक का। जंगल सुंदर, गहरे और गहरे हैं,   \u000aलेकिन मेरे पास रखने के वादे हैं,   \u000aऔर सोने से पहले मीलों दूर जाना है,   \u000aऔर सोने से पहले मीलों दूर जाना है.'),'{"targetLang":"hi","fromCache":false}','2026-10-28 11:26:44');
INSERT INTO session_activities VALUES(109,'a0a8d727-a897-47b5-8836-b50d08e60592','TRANSLATE',unistr('Whose woods these are I think I know.   \u000aHis house is in the village though;   \u000aHe will not see me stopping here   \u000aTo watch his woods fill up with snow.   \u000a\u000aMy little horse must think it queer   \u000aTo stop without a farmhouse near   \u000aBetween the woods and frozen lake   \u000aThe darkest evening of the year.   \u000a\u000aHe gives his harness bells a shake   \u000aTo ask if there is some mistake.   \u000aThe only other sound’s the sweep   \u000aOf easy wind and downy flake.   \u000a\u000aThe woods are lovely, dark and deep,   \u000aBut I have promises to keep,   \u000aAnd miles to go before I sleep,   \u000aAnd miles to go before I sleep.'),unistr('ഇവ ആരുടെ കാടുകളാണെന്ന് എനിക്കറിയാം. അവന്റെ വീട് ഗ്രാമത്തിലാണ്;   \u000aഞാൻ ഇവിടെ നിർത്തുന്നത് അവൻ കാണില്ല   \u000aഅവന്റെ കാടുകളിൽ മഞ്ഞ് നിറയുന്നത് കാണാൻ. എന്റെ ചെറിയ കുതിര അത് രസകരമാണെന്ന് ചിന്തിക്കണം   \u000aസമീപത്ത് ഒരു ഫാംഹൗസ് ഇല്ലാതെ നിർത്താൻ   \u000aകാടിനും മരവിച്ച തടാകത്തിനുമിടയിൽ   \u000aവർഷത്തിലെ ഏറ്റവും ഇരുണ്ട സായാഹ്നം. അവൻ തന്റെ ഹാർനെസ് ബെല്ലുകൾ കുലുക്കുന്നു   \u000aഎന്തെങ്കിലും തെറ്റുണ്ടോ എന്ന് ചോദിക്കാൻ. മറ്റൊരു ശബ്ദം സ്വീപ്പ് മാത്രമാണ്   \u000aഎളുപ്പത്തിൽ വീശുന്ന കാറ്റും വീശിയടിക്കുന്ന ഫ്ലേക്കും. കാടുകൾ മനോഹരവും ഇരുണ്ടതും ആഴമേറിയതുമാണ്,   \u000aഎന്നാൽ എനിക്ക് പാലിക്കാൻ വാഗ്ദാനങ്ങളുണ്ട്,   \u000aഞാൻ ഉറങ്ങുന്നതിനുമുമ്പ് മൈലുകൾ സഞ്ചരിക്കേണ്ടതുണ്ട്,   \u000aഞാൻ ഉറങ്ങുന്നതിനുമുമ്പ് മൈലുകൾ സഞ്ചരിക്കേണ്ടതുണ്ട്.'),'{"targetLang":"ml","fromCache":false}','2026-10-28 11:26:51');
INSERT INTO session_activities VALUES(110,'a0a8d727-a897-47b5-8836-b50d08e60592','SAVE',unistr('Whose woods these are I think I know.   \u000aHis house is in the village though;   \u000aHe will not see me stopping here   \u000aTo watch his woods fill up with snow.   \u000a\u000aMy little horse must think it queer   \u000aTo stop without a farmhouse near   \u000aBetween the woods and frozen lake   \u000aThe darkest evening of the year.   \u000a\u000aHe gives his harness bells a shake   \u000aTo ask if there is some mistake.   \u000aThe only other sound’s the sweep   \u000aOf easy wind and downy flake.   \u000a\u000aThe woods are lovely, dark and deep,   \u000aBut I have promises to keep,   \u000aAnd miles to go before I sleep,   \u000aAnd miles to go before I sleep.\u000a'),'Manuscript','{"historyId":"HIST-1793167026446"}','2026-10-28 11:27:06');
INSERT INTO session_activities VALUES(111,'a0a8d727-a897-47b5-8836-b50d08e60592','ANALYZE',unistr('Something there is that doesn’t love a wall,\u000aThat sends the frozen-ground-swell under it,\u000aAnd spills the upper boulders in the sun;\u000aAnd makes gaps even two can pass abreast.\u000aThe work of hunters is another thing:\u000aI have come after them and made repair\u000aWhere they have left not one stone on a stone,\u000aBut they would have the rabbit out of hiding,\u000aTo please the yelping dogs. The gaps I mean,\u000aNo one has seen them made or heard them made,\u000aBut at spring mending-time we find them there.\u000aI let my neighbor know beyond the hill;\u000aAnd on a day we meet to walk the line\u000aAnd set the wall between us once again.\u000aWe keep the wall between us as we go.\u000aTo each the boulders that have fallen to each.\u000aAnd some are loaves and some so nearly balls\u000aWe have to use a spell to make them balance:\u000a‘Stay where you are until our backs are turned!’\u000aWe wear our fingers rough with handling them.\u000aOh, just another kind of out-door game,\u000aOne on a side. It comes to little more:\u000aThere where it is we do not need the wall:\u000aHe is all pine and I am apple orchard.\u000aMy apple trees will never get across\u000aAnd eat the cones under his pines, I tell him.\u000aHe only says, ‘Good fences make good neighbors.’\u000aSpring is the mischief in me, and I wonder\u000aIf I could put a notion in his head:\u000a‘Why do they make good neighbors? Isn’t it\u000aWhere there are cows? But here there are no cows.\u000aBefore I built a wall I’d ask to know\u000aWhat I was walling in or walling out,\u000aAnd to whom I was like to give offense.\u000aSomething there is that doesn''t love a wall,\u000aThat wants it down.’ I could say ‘Elves’ to him,\u000aBut it’s not elves exactly, and I’d rather\u000aHe said it for himself. I see him there\u000aBringing a stone grasped firmly by the top\u000aIn each hand, like an old-stone savage armed.\u000aHe moves in darkness as it seems to me,\u000aNot of woods only and the shade of trees.\u000aHe will not go behind his father’s saying,\u000aAnd he likes having thought of it so well\u000aHe says again, ‘Good fences make good neighbors.’\u000a'),'387 words, 17 sentences','{"sourceName":"Manuscript","wordCount":387}','2026-10-28 12:06:13');
